listen('click',e=>{if(e.target.closest('#saved-view-update'))saveCurrentView($('saved-view-name').value,true);if(e.target.closest('#saved-view-delete'))deleteSavedView()});

function render(){if($('organic-live-host'))$('organic-live-host').hidden=state.view!=='overview';syncSavedViews();syncDateControls();syncReviewControls();let [label,intro]=views.find(v=>v[0]===state.view).slice(1);$('view-title').textContent=label;$('crumb').textContent=label;$('scope').textContent=scopeText();updateChatScope();$('print-context').textContent='SYNTHETIC SAMPLE DATA · '+(state.site==='all'?'Both properties':state.site==='faq'?'MedicareFAQ':'Medicare Compared')+' · '+scopeText()+' · '+(state.pageType==='all'?'All page types':labels[state.pageType])+' · '+state.device+' devices';root.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===state.view));let rs=filtered(),pr=filtered(true),now=sum(rs),prev=sum(pr);if(!rs.length&&state.view!=='measurement'&&state.view!=='opportunities'&&state.view!=='connections'){$('app').innerHTML='<section class="card empty"><strong>No sample data matches these filters.</strong><p>Choose another property or page type.</p></section>';return}$('app').innerHTML=({overview:()=>overview(rs,pr,now,prev),acquisition:()=>acquisition(rs,pr,now,prev),leads:()=>leadsView(rs,pr,now,prev),content:()=>contentView(rs,pr,now,prev),opportunities:()=>opportunitiesView(rs),measurement:measurementView,connections:connectionsView,keywords:()=>keywordsView(rs)})[state.view]();root.querySelectorAll('.chart circle[data-tip]').forEach(c=>{c.addEventListener('mouseenter',e=>{let tip=c.closest('.chart').querySelector('.chart-tip');tip.textContent=c.dataset.tip;tip.style.display='block'});c.addEventListener('mousemove',e=>{let chart=c.closest('.chart'),tip=chart.querySelector('.chart-tip'),r=chart.getBoundingClientRect();tip.style.left=Math.min(e.clientX-r.left+9,r.width-170)+'px';tip.style.top=Math.max(0,e.clientY-r.top-32)+'px'});c.addEventListener('mouseleave',()=>c.closest('.chart').querySelector('.chart-tip').style.display='none')})}

let drawerPage=null,drawerTab='performance',returnFocus=null;
function presentDrawer(html){if(!$('drawer').classList.contains('open'))returnFocus=document.activeElement;$('drawer-content').innerHTML=html;$('drawer').classList.add('open');document.body.style.overflow='hidden';$('drawer-content').querySelector('[data-close]').focus()}
