function openPage(id,tabName='performance'){let p=pages.find(x=>x.id===id);if(!p)return;drawerPage=id;drawerTab=tabName;let rs=filtered().filter(r=>r.page===id),d=sum(rs),prior=sum(filtered(true).filter(r=>r.page===id)),ks=keywordRows.filter(k=>k.page===id);let body='';
if(tabName==='performance')body=`<div class="drawer-metrics"><div><span>Organic sessions</span><strong>${fmt(d.sessions)}</strong><br>${delta(d.sessions,prior.sessions)}</div><div><span>Valid leads</span><strong>${fmt(d.leads)}</strong><br>${delta(d.leads,prior.leads)}</div><div><span>Session-to-lead rate</span><strong>${pct(d.rate)}</strong></div><div><span>Bounce rate</span><strong>${pct(d.bounceRate)}</strong></div></div><h3>Organic sessions over time</h3>${comparisonChart(rs,'sessions')}<div class="drawer-caption">PostHog · ${state.grain} buckets · aligned period buckets</div><h3>Device performance</h3><div class="data-table"><table style="min-width:0"><thead><tr><th>Device</th><th class="num">Sessions</th><th class="num">Lead rate</th><th class="num">Bounce</th></tr></thead><tbody>${aggregateBy(rs,r=>r.device).map(x=>`<tr><td>${x.name}</td><td class="num">${fmt(x.sessions)}</td><td class="num">${pct(x.rate)}</td><td class="num">${pct(x.bounceRate)}</td></tr>`).join('')}</tbody></table></div>`;
if(tabName==='search')body=`<div class="drawer-metrics"><div><span>Google Web clicks</span><strong>${fmt(d.clicks)}</strong></div><div><span>Impressions</span><strong>${fmt(d.impressions)}</strong></div><div><span>Search CTR</span><strong>${pct(d.ctr)}</strong></div><div><span>Tracked keywords</span><strong>${ks.length}</strong></div></div><h3>Tracked queries <span class="pill">Semrush</span></h3>${ks.map(k=>`<button class="query-row" data-keyword="${k.id}"><span>${safe(k.query)}<small>${fmt(k.volume)} monthly searches · KD ${k.difficulty}</small></span><strong>#${k.rank} →</strong></button>`).join('')||'<p>No tracked queries for this page.</p>'}<div class="drawer-caption">GSC metrics use the selected period. Semrush rankings use the Oct 5 snapshot.</div>`;
if(tabName==='history')body=pageHistory(id);
if(tabName==='actions')body=`<h3>Create a review action</h3><label class="edit-label" for="action-note">Proposed action</label><textarea id="action-note" rows="3" placeholder="Describe the change or investigation"></textarea><div class="edit-grid"><div><label class="edit-label" for="action-owner">Owner</label><select id="action-owner"><option>Charlie</option><option>Joe</option><option>CRO team</option><option>Pepper</option></select></div><div><label class="edit-label" for="action-date">Follow-up</label><input id="action-date" type="date" value="2026-10-13"></div></div><button class="button primary" data-save-page="${id}">Add to review</button><p class="drawer-caption">Saved locally in this demo.</p>${reviewList(id)}`;
presentDrawer(`<button class="drawer-close" aria-label="Close detail" data-close>×</button><div class="eyebrow">${p.site==='faq'?'MedicareFAQ':'Medicare Compared'} · ${labels[p.type]}</div><h2>${safe(p.name)}</h2><p class="drawer-period">${scopeText()}</p><div class="tabs drawer-tabs">${[['performance','Performance'],['search','Search'],['history','History'],['actions','Actions']].map(([key,label])=>`<button data-page-tab="${key}" class="${key===tabName?'active':''}">${label}</button>`).join('')}</div>${body}`)
}

function historyStore(){try{return JSON.parse(localStorage.getItem('organic-demo-history')||'{"entries":[],"statuses":{}}')}catch{return {entries:[],statuses:{}}}}
function historyEntries(id){let p=pages.find(p=>p.id===id),index=pages.findIndex(p=>p.id===id),themes=[['Content update','Clarified coverage details and refreshed the opening answer.'],['Internal links','Added relevant links from supporting pages to this landing page.'],['CTA test','Introduced a contextual help prompt near the comparison section.']],type=themes[index%3];let seeds=[{id:id+'-sep26',page:id,date:'2026-09-26',type:type[0],title:type[1],owner:type[0]==='CTA test'?'CRO team':'Charlie',status:'Monitoring',note:'Review lead quality and traffic mix before drawing conclusions.'},{id:id+'-sep12',page:id,date:'2026-09-12',type:'Content update',title:'Revised headings and expanded answers around the primary search intent.',owner:'Charlie',status:'Completed',note:'Initial observation window complete. Continue monitoring seasonal effects.'}];let stored=historyStore();return [...seeds,...stored.entries.filter(x=>x.page===id)].map(x=>({...x,status:stored.statuses[x.id]||x.status})).sort((a,b)=>b.date.localeCompare(a.date)||b.id.localeCompare(a.id))}
